const edition = globalThis.makeSubjectEdition({"year":2015,"grade":"9-11","tasksFile":"ZR_1415_9-11.pdf","answersFile":"reviewed-9-11.pdf","title":"Эпоха Возрождения","subject":"golden-fleece","contest":"Золотое руно","letters":"ABCD","count":60,"language":"ru","points":3,"sourceFile":"sources/golden-fleece/2015/9-11.json","sections":[{"start":1,"title":"Общие сведения"},{"start":16,"title":"Идеи"},{"start":31,"title":"Чувства"},{"start":46,"title":"Образы"}],"reviewedKey":true}, [{"title":"Первые залы галереи","question":"Этот представитель рода Медичи считается создателем всемирно известной галереи Уффици.","choices":["Козимо I","Франческо I","Лоренцо","Екатерина"],"answer":1,"steps":["Козимо I заказал здание Уффици для учреждений.","Его сын Франческо I устроил там пространство для собраний искусства и заказал зал Трибуна."]},{"title":"Покушение 1478 года","question":"Покушение на Лоренцо и Джулиано Медичи в 1478 году вошло в историю под названием …","choices":["«Заговор Маджоне»","«Заговор Пацци»","«Амбуазский заговор»","«Пороховой заговор»"],"answer":1,"steps":["Участники заговора из семьи Пацци и их союзники напали на братьев Медичи во время мессы.","Джулиано убили, а Лоренцо выжил."]},{"title":"Ранняя конная статуя","question":"Одна из первых конных статуй эпохи Возрождения работы Донателло посвящена этому кондотьеру.","choices":["Б. Коллеони","Л. Сфорца","Э. да Нарни","Ф. Буссоне"],"answer":2,"steps":["Донателло отлил из бронзы фигуру кондотьера Эразмо да Нарни по прозвищу Гаттамелата.","Памятник поставили в Падуе, рядом с базиликой Святого Антония."]},{"title":"Должность ди Риенци","question":"Кола ди Риенци возглавлял Римскую республику, провозгласив себя …","choices":["консулом","патрицием","сенатором","трибуном"],"answer":3,"steps":["Кола ди Риенци использовал название древнеримской должности народного трибуна.","В 1347 году он попытался под этим титулом восстановить республиканское управление Римом."]},{"title":"Гуманист на службе","question":"Этот английский гуманист эпохи Возрождения занимал один из высших постов государства.","choices":["Д. Уиклиф","У. Шекспир","Т. Мор","Дж. Чосер"],"answer":2,"steps":["Томас Мор написал «Утопию» и служил Генриху VIII.","С 1529 по 1532 год он занимал пост лорда-канцлера."]},{"title":"Должность Альберти","question":"Л. Б. Альберти, называемый «самым универсальным гением Раннего Возрождения», долгое время работал в Ватикане в этой должности.","choices":["Священник","Государственный секретарь","Библиотекарь","Секретарь курии"],"answer":3,"steps":["Альберти составлял документы для папской курии.","Его служба была связана со знанием латыни, которым он пользовался и в собственных трактатах."]},{"title":"Фрески в Ферраре","question":"В этом фераррском дворце сохранились фрески мастеров Раннего Возрождения Ф. дель Косса и К. Тура.","choices":["Палаццо Ручеллаи","Вилла Боргезе","Вилла д`Эсте","Палаццо Скифанойя"],"answer":3,"steps":["Зал месяцев дворца Скифанойя украшен фресками с трудом людей, знаками Зодиака и сценами двора.","В росписи участвовали мастера феррарской школы."]},{"title":"Спор драматургов","question":"Конфликт между английскими драматургами на рубеже XVI–XVII вв., получивший отражение в сценической полемике, назывался …","choices":["«война актеров»","«война сценаристов»","«война драматургов»","«война театров»"],"answer":3,"steps":["В пьесах Бена Джонсона, Джона Марстона и Томаса Деккера появлялись сатирические портреты соперников.","Эта полемика со сцены получила название «войны театров»."]},{"title":"Кружки риторики","question":"В XVI веке сторонников развития национальной культуры в Нидерландах называли …","choices":["гёзы","статхаудеры","пенсионарии","редерейкеры"],"answer":3,"steps":["В городах Нидерландов редерейкеры объединялись в палаты риторики.","Они сочиняли на местном языке стихи и пьесы и устраивали публичные состязания."]},{"title":"Лозунг папы","question":"Кто из римских пап начала XVI века поддержал клич «Долой варваров!»?","choices":["Юлий II","Климент VII","Лев Х","Александр VI"],"answer":0,"steps":["Юлий II воевал за влияние Папской области на Апеннинском полуострове.","На одном из этапов он собрал Священную лигу, чтобы вытеснить из Италии французские войска."]},{"title":"Флоренция после Медичи","question":"После нашествия французов в 1494 году правителем Флоренции стал …","choices":["Н. Макиавелли","Дж. Савонарола","П. Содерини","П. Медичи"],"answer":1,"steps":["После вступления армии Карла VIII Медичи изгнали из Флоренции.","Доминиканец Савонарола приобрёл решающее влияние на новую республику благодаря проповедям и политическим инициативам."]},{"title":"Папа и идеи Лютера","question":"Кто из римских пап эпохи Ренессанса первым выступил против идей М. Лютера?","choices":["Александр VI","Лев X","Юлий II","Климент VII"],"answer":1,"steps":["Лев X издал буллу с осуждением ряда положений Лютера.","Когда реформатор публично сжёг буллу и не отрёкся от идей, папа отлучил его от церкви."]},{"title":"Придворный хирург","question":"Этот французский придворный врач считается одним из отцов современной хирургии.","choices":["А. Паре","Г. Фаллопий","Р. Гийом","К. Варолий"],"answer":0,"steps":["Амбруаз Паре применял более щадящие перевязки вместо традиционного прижигания огнестрельных ран.","Он работал при французском дворе и описывал методы хирургии по собственному опыту."]},{"title":"Остров астронома","question":"Этот остров был пожалован королём Фредериком II в пожизненное пользование астроному Т. Браге для строительства обсерватории.","choices":["Тенерифе","Вен","Св. Елены","Гавайи"],"answer":1,"steps":["Фредерик II предоставил Тихо Браге остров Вен в проливе Эресунн.","Там астроном построил Ураниборг и Стьернеборг для наблюдений без телескопа."]},{"title":"Избрание императора","question":"Этот монарх получил имперскую корону благодаря финансовой поддержке Фуггеров.","choices":["Фридрих III","Карл IV Люксембургский","Карл V Габсбург","Фердинанд II"],"answer":2,"steps":["В 1519 году выборщики Священной Римской империи выбирали между Карлом и другими претендентами.","Средства, полученные Карлом от банковского дома Фуггеров, помогли обеспечить поддержку."]},{"title":"Философия Христа","question":"В «Философии Христа» Эразм Роттердамский призывал …","choices":["отказаться от Библии","ликвидировать католическую церковь","отбросить античное наследие","вернуться к истокам христианства"],"answer":3,"steps":["Эразм призывал читать Евангелие и древние христианские тексты и жить по их нравственному смыслу.","Он выпустил издание Нового Завета на греческом и латыни."]},{"title":"Сверхновая 1572 года","question":"В этом созвездии датский астроном Т. Браге в 1572 году обнаружил сверхновую звезду.","choices":["Кассиопея","Змееносец","Телец","Волк"],"answer":0,"steps":["Браге увидел новую звезду среди звёзд Кассиопеи.","Он не обнаружил у неё заметного смещения относительно далёких звёзд, что ставило под сомнение представление о неизменном месте звёзд."]},{"title":"Предвестник журналистики","question":"Творчество этого писателя предвосхитило появление журналистики.","choices":["М. Сервантес","Л. Ариосто","П. Аретино","Т. Тассо"],"answer":2,"steps":["Аретино распространял сатиру и отклики на события своего времени.","Его печатные собрания писем делали частную переписку частью публичной жизни."]},{"title":"Паук, муравей и пчела","question":"Этот философ выделил три основных вида познания: «путь паука», «путь муравья» и «путь пчелы».","choices":["М. Монтень","М. Фичино","Ф. Бэкон","Эразм Роттердамский"],"answer":2,"steps":["У Бэкона паук ткёт из себя, а муравей лишь складывает собранное.","Пчела преобразует материал, как исследователь соединяет факты с рассуждением."]},{"title":"Правитель и мораль","question":"С именем этого мыслителя связывают термин, означающий возможность правителя пренебречь нормами морали ради достижения благополучия государства.","choices":["И. Лойола","М. Лютер","М. Монтень","Н. Макиавелли"],"answer":3,"steps":["Макиавелли в «Государе» обсуждал поступки правителя, необходимые для сохранения власти.","С последующим толкованием этих идей связан термин «макиавеллизм»."]},{"title":"Единица ускорения","question":"Единица измерения ускорения, получившая своё название в честь итальянского астронома и физика, называется …","choices":["стокс","эрг","гал","пуаз"],"answer":2,"steps":["Гал — единица ускорения, равная одному сантиметру в секунду за секунду.","Её назвали в честь Галилея, изучавшего ускорение при падении тел."]},{"title":"Повседневная жизнь","question":"Этот мыслитель в одном из своих произведений написал: «А сумел ты обдумать свою повседневную жизнь и пользоваться ею как следует? Если да, то ты уже совершил величайшее дело».","choices":["И. Лойола","М. Лютер","М. Монтень","Н. Макиавелли"],"answer":2,"steps":["Монтень разбирает этот вопрос в главе «Об опыте».","Само умение жить обдуманно он ставит выше отдельных громких достижений."]},{"title":"Пьеса «Аминта»","question":"В этом жанре написано произведение Т. Тассо «Аминта».","choices":["Комедия","Трагедия","Трагедия ужасов","Пасторальная драма"],"answer":3,"steps":["Тассо поместил героев «Аминты» в условный мир пастухов, нимф и лесов.","Такая любовная пьеса на пастушеском фоне относится к пасторальной драме."]},{"title":"Сборник Рейхлина","question":"Этот сборник И. Рейхлин составил из высказываний своих единомышленников.","choices":["«Письма тёмных людей»","«Письма знаменитых людей»","«Похвала глупости»","«Разговоры запросто»"],"answer":1,"steps":["Иоганн Рейхлин издал «Письма знаменитых людей», чтобы представить голоса своих сторонников.","«Письма тёмных людей» — другое произведение, сатирический ответ его противников по спору."]},{"title":"Герой пьесы Болта","question":"Пьеса Р. Болта «Человек для любой поры» посвящена жизни и деятельности этого великого мыслителя.","choices":["Т. Мор","Т. Кампанелла","Ф. Бэкон","Л. Мерсье"],"answer":0,"steps":["Болт показал конфликт Томаса Мора с Генрихом VIII из-за подчинения английской церкви королю.","Мор отказался признать требуемую присягу и был казнён."]},{"title":"Стихи о философе","question":"Кто из поэтов «серебряного» века посвятил своё стихотворение итальянскому философу, выдвинувшему теорию о бесконечности вселенной?","choices":["А. Блок","Н. Гумилёв","С. Есенин","И. Бунин"],"answer":3,"steps":["Иван Бунин написал стихотворение «Джордано Бруно».","Именно Бруно среди мыслителей Возрождения отстаивал идею бесконечной Вселенной."]},{"title":"Жанр гуманистов","question":"Гуманисты Северного Возрождения в отличие от итальянцев больше тяготели к жанру …","choices":["послания","философского диалога","философского трактата","сатиры"],"answer":3,"steps":["«Похвала глупости» Эразма и «Корабль дураков» Себастьяна Бранта высмеивают пороки общества.","С этими произведениями связана традиция гуманистической сатиры к северу от Альп."]},{"title":"Химия и медицина","question":"Направление в медицине, которое в эпоху Возрождения развивал немецкий врач и алхимик Ф. Гогенгейм, называется …","choices":["ятрохимия","хрономедицина","фотобиология","биофизика"],"answer":0,"steps":["Филипп фон Гогенгейм известен как Парацельс.","Он применял вещества и способы их приготовления в лечении, что стало одной из основ ятрохимии."]},{"title":"Книга о горном деле","question":"Этот учёный создал научный труд «О горном деле и металлургии в двенадцати книгах».","choices":["Г. Галилей","Г. Агрикола","Ф. Бэкон","Леонардо да Винчи"],"answer":1,"steps":["Георгий Агрикола подробно описал добычу и обработку руды в De re metallica.","Его книга сопровождалась гравюрами шахт и механизмов."]},{"title":"Три закона движения","question":"Этот немецкий астроном утверждал, что планеты вращаются вокруг Солнца, и создал три закона их движения.","choices":["Т. Браге","И. Кеплер","Дж. Бруно","Н. Коперник"],"answer":1,"steps":["Кеплер обосновал эллиптическую форму орбит и описал закономерности движения планет.","Он опирался на точные наблюдения Тихо Браге."]},{"title":"Существо из сказки","question":"Согласно сказке Леонардо да Винчи, это мифическое создание превратило север Африки в пустыню.","choices":["Василиск","Гаргулья","Русалка","Левиафан"],"answer":0,"steps":["Василиска в средневековых преданиях наделяли убийственным взглядом и ядом.","Леонардо использовал преувеличенную разрушительную силу существа в рассказе о пустыне."]},{"title":"Подражание поэту","question":"Направление в поэзии в эпоху Возрождения, ориентировавшееся на лирику итальянского поэта XIV века, получило название …","choices":["кальвинизм","маньеризм","петраркизм","маринизм"],"answer":2,"steps":["Образцами для поэтов стали сонеты Франческо Петрарки к Лауре.","Они перенимали его формы стихов и приёмы рассказа о любви, отсюда слово «петраркизм»."]},{"title":"Кружок гуманистов","question":"Кружок гуманистов, основанный П. Летом в середине XV века, получил название … .","choices":["Платоновская академия в Кареджи","Римская академия","Академия Понтаниана","Нюрнбергский кружок"],"answer":1,"steps":["Помпонио Лето и его ученики занимались в Риме культурой и языком античности.","Их объединение получило название Римской академии."]},{"title":"Литературный диалект","question":"Этот диалект был положен в основу итальянского литературного языка в эпоху Возрождения.","choices":["Лигурский","Неаполитанский","Тосканский","Римский"],"answer":2,"steps":["Данте, Петрарка и Боккаччо писали на тосканской основе.","Высокий авторитет их произведений помог этой разновидности речи стать основой литературного итальянского."]},{"title":"Новеллы королевы","question":"Произведение Маргариты Наваррской, написанное под влиянием сборника новелл Дж. Боккаччо, называется…","choices":["«Корабль»","«Гептамерон»","«Зерцало грешной души»","«Перлы перла принцесс»"],"answer":1,"steps":["Как у Боккаччо, персонажи Маргариты Наваррской рассказывают друг другу истории.","Сборник получил название «Гептамерон», связанное с семью завершёнными днями рассказов."]},{"title":"Город «Мандрагоры»","question":"В этом городе происходит действие учёной комедии Н. Макиавелли «Мандрагора».","choices":["Флоренция","Падуя","Венеция","Неаполь"],"answer":0,"steps":["Действие «Мандрагоры» разворачивается во Флоренции.","Макиавелли изображает обман, в который вовлечены молодой Каллимако, супруги и монах."]},{"title":"Античный сюжет","question":"Основой этого произведения У. Шекспира стал сюжет «Менехмов» Т. Плавта.","choices":["«Комедия ошибок»","«Венецианский купец»","«Двенадцатая ночь»","«Много шума из ничего»"],"answer":0,"steps":["В «Менехмах» Плавт строит комизм на том, что близнецов принимают друг за друга.","Шекспир использует этот ход в «Комедии ошибок», добавив ещё одну пару близнецов."]},{"title":"Герой и его ремёсла","question":"Пьеса У. Шекспира, герой которой утверждает, что он разносчик, чесальщик, медвежатник и медник, называется …","choices":["«Венецианский купец»","«Виндзорские насмешницы»","«Укрощение строптивой»","«Двенадцатая ночь, или Что угодно»"],"answer":2,"steps":["Сценой с Кристофером Слаем открывается «Укрощение строптивой».","Ремесленника, которого разыграли и выдали за лорда, затем приглашают посмотреть комедию."]},{"title":"Ранняя комедия Ариосто","question":"Эта комедия Л. Ариосто изначально была написана прозой.","choices":["«Сводня»","«Чернокнижник»","«Студенты»","«Шкатулка» («Комедия о сундуке»)"],"answer":3,"steps":["«Шкатулка», или La Cassaria, была поставлена в Ферраре в прозе.","Сам Ариосто позднее переработал её в стихах."]},{"title":"Автор «Опытов»","question":"Кто из представленных мыслителей эпохи Возрождения не писал комедий?","choices":["П. Аретино","М. Монтень","Дж. Бруно","Н. Макиавелли"],"answer":1,"steps":["Аретино, Бруно и Макиавелли оставили комедии.","Монтень известен прежде всего как автор «Опытов», в которых обсуждает отдельные вопросы в свободной форме."]},{"title":"Чем живёт остров","question":"Чем питались жители острова Руах в романе Ф. Рабле?","choices":["Ветром","Дождем","Солнцем","Снегом"],"answer":0,"steps":["Название Руах отсылает к слову, которое может обозначать ветер и дыхание.","Рабле обыгрывает эту связь, изображая жителей, питающихся ветром."]},{"title":"Рождение Гаргантюа","question":"Рождение какой римской богини Франсуа Рабле упоминает, описывая появление Гаргантюа на свет?","choices":["Юноны","Венеры","Минервы","Дианы"],"answer":2,"steps":["В главе о рождении Гаргантюа Рабле вспоминает Минерву, появившуюся из головы Юпитера. Писатель приводит этот миф среди примеров необычного появления на свет.","Минерву почитали в Риме. Её греческая параллель — Афина."],"references":["https://athena.unige.ch/athena/rabelais/rabelais-gargantua.html","https://www.britannica.com/topic/Minerva-Roman-goddess"],"taskUrl":"https://runodog.ru/ZR_1415/ZR_1415_9-11.pdf#page=1","adaptation":"Редакция вопроса проверена по первоисточникам."},{"title":"Масленичные игры","question":"Этот композитор эпохи Возрождения прославился своими «масленичными играми».","choices":["Г. Сакс","У. Бёрд","Ж. Депре","О. Лассо"],"answer":0,"steps":["Ганс Сакс, нюрнбергский мейстерзингер, сочинял короткие комические пьесы для масленичных праздников.","Такие пьесы известны как Fastnachtsspiele."]},{"title":"Песня Реформации","question":"Один из образцов этого жанра Г. Гейне назвал «Марсельезой Реформации».","choices":["Фроттола","Месса","Мадригал","Протестантский хорал"],"answer":3,"steps":["Гейне так назвал «Господь — наш крепкий оплот», хорал, связанный с Лютером.","Хорал — песнопение на родном языке, предназначенное для пения общиной."]},{"title":"Сборник новелл","question":"Этот писатель эпохи Возрождения создал сборник «Новеллино», в одной из новелл которого он одним из первых описал историю трагической гибели двух влюбленных.","choices":["У. Шекспир","К. Марло","Ф. Петрарка","Т. Мазуччо"],"answer":3,"steps":["Мазуччо Салернитано включил в «Новеллино» рассказ о Мариотто и Джанноцце.","Сюжет об их разлуке и гибели предвосхищает некоторые мотивы истории Ромео и Джульетты."]},{"title":"Площадь со скульптурами","question":"На какой площади Флоренции рядом с Палаццо Веккьо стоят копия «Давида» Микеланджело и «Геркулес и Какус» Баччо Бандинелли?","choices":["Площадь Синьории","Площадь Святой Троицы","Соборная площадь","Площадь Республики"],"answer":0,"steps":["Палаццо Веккьо выходит на площадь Синьории. Нынешний «Давид» на площади — копия, оригинал хранится в Галерее Академии.","Рядом стоит оригинальная скульптура «Геркулес и Какус», созданная Баччо Бандинелли."],"references":["https://press.comune.fi.it/it/comunicato/493152","https://www.uffizi.it/en/artworks/oval-signoria-piazza"],"taskUrl":"https://runodog.ru/ZR_1415/ZR_1415_9-11.pdf#page=2","adaptation":"Редакция вопроса проверена по первоисточникам.","figure":{"src":"assets/golden-fleece/2015/lessons/9-11/46.webp","alt":"Статуи перед фасадом городского дворца","width":527,"height":560,"detailSrc":"assets/golden-fleece/2015/lessons/9-11/46-detail.webp"}},{"title":"Мастер колокольни","question":"Автор этого архитектурного произведения был учеником …","choices":["А. ди Камбио","Чимабуэ","Н. Пизано","К. Космати"],"answer":1,"steps":["Колокольню Флорентийского собора начал строить Джотто.","Художественная традиция называет его учителем Чимабуэ, о чём рассказывал Вазари."],"figure":{"src":"assets/golden-fleece/2015/lessons/9-11/47.webp","alt":"Каменная башня с цветной облицовкой","width":130,"height":173}},{"title":"Миф на фреске","question":"В образе этого мифологического персонажа на фреске «Страшный суд» Микеланджело изобразил папского церемониймейстера Бьяджо да Чезена.","choices":["Прометей","Арес","Аид","Минос"],"answer":3,"steps":["В нижней части «Страшного суда» изображён Минос, судья подземного мира.","По биографам художника, Микеланджело дал этой фигуре черты Бьяджо да Чезена."]},{"title":"Мягкие переходы","question":"Автор этой картины дал теоретическое описание техники живописи «сфумато».","choices":["Леонардо да Винчи","С. Боттичелли","Микеланджело","С. Мартини"],"answer":0,"steps":["Сфумато позволяет смягчить контуры с помощью постепенного перехода света в тень.","Леонардо применял этот приём на лице и в пейзаже «Моны Лизы»."],"figure":{"src":"assets/golden-fleece/2015/lessons/9-11/49.webp","alt":"Портрет женщины на фоне пейзажа","width":128,"height":191}},{"title":"Двери баптистерия","question":"Этот скульптор создал бронзовые рельефы ворот баптистерия Сан-Джованни во Флоренции со сценами из жизни Иоанна Крестителя.","choices":["Л. Гиберти","Микеланджело","А. Пизано","Донателло"],"answer":2,"steps":["Андреа Пизано создал южные бронзовые двери баптистерия.","Большую часть их панелей занимают эпизоды истории Иоанна Крестителя."]},{"title":"Книга на картине","question":"Эта картина Рафаэля известна как «Мадонна с книгой».","choices":["«Сикстинская мадонна»","«Мадонна Грандука»","«Малая мадонна Каупера»","«Мадонна Конестабиле»"],"answer":3,"steps":["На небольшом круглом тондо младенец и Мария смотрят на раскрытую книгу.","Произведение называют «Мадонной Конестабиле» по фамилии прежних владельцев."],"figure":{"src":"assets/golden-fleece/2015/lessons/9-11/51.webp","alt":"Круглая картина с женщиной и младенцем","width":147,"height":147}},{"title":"Гравюры на дереве","question":"Этот живописец является одним из крупнейших мастеров ксилографии эпохи Возрождения.","choices":["Т. Рименшнайдер","Г. Гольбейн Ст.","А. Дюрер","М. Грюневальд"],"answer":2,"steps":["Дюрер создавал ксилографии, например цикл «Апокалипсис».","При печати линии изображения переносятся на бумагу с выступающих частей деревянной формы."],"figure":{"src":"assets/golden-fleece/2015/lessons/9-11/52.webp","alt":"Рисунок мужчины в меховом головном уборе","width":129,"height":169}},{"title":"Братство в городе","question":"Этот художник Северного Возрождения был почётным членом Братства Богоматери.","choices":["А. Дюрер","Я. ван Эйк","П. Брейгель Ст.","И. Босх"],"answer":3,"steps":["Босх жил в Хертогенбосе и входил в местное Братство Богоматери, религиозное объединение горожан.","Это зафиксировано в записях братства."]},{"title":"Реализм живописи","question":"Автор этой картины одним из первых в Европе воплотил реалистическую концепцию творчества.","choices":["Джотто","Рафаэль","Я. ван Эйк","С. Боттичелли"],"answer":2,"steps":["На портрете четы Арнольфини Ян ван Эйк воспроизвёл отражение комнаты в выпуклом зеркале и тщательно передал предметы быта.","Такие детали характерны для реализма ранней нидерландской школы."],"figure":{"src":"assets/golden-fleece/2015/lessons/9-11/54.webp","alt":"Две фигуры у окна, между ними зеркало","width":128,"height":177}},{"title":"Подлинник статуи","question":"В этом музее находится подлинник скульптуры Микеланджело «Давид».","choices":["Галерея Уффици","Палаццо Питти","Галерея Академии","Палаццо Веккьо"],"answer":2,"steps":["Чтобы защитить мраморного «Давида» от непогоды, его перенесли с площади в Галерею Академии.","На прежнем месте у Палаццо Веккьо стоит копия."]},{"title":"Портреты Лютера","question":"Этот художник дружил с М. Лютером и создал множество его портретов.","choices":["Г. Гольбейн Мл.","П. Брейгель Ст.","Л. Кранах Ст.","Л. Кранах Мл."],"answer":2,"steps":["Лукас Кранах Старший работал в Виттенберге и был близок к Лютеру.","Его портреты показывают реформатора в монашеской одежде, а позднее в облике проповедника."],"figure":{"src":"assets/golden-fleece/2015/lessons/9-11/56.webp","alt":"Лицо мужчины в тёмном головном уборе","width":172,"height":138}},{"title":"Алтарь в Венеции","question":"В этой венецианской церкви хранится алтарная картина Тициана «Вознесение Богоматери».","choices":["Санта-Мария-делла-Салюте","Сан-Марко","Санта-Мария Глориоза-деи-Фрари","Санта-Мария Формоза"],"answer":2,"steps":["Большое «Вознесение Богоматери» Тициан написал для главного алтаря францисканской базилики Санта-Мария-Глориоза-деи-Фрари.","Композицию можно увидеть в этой церкви."],"figure":{"src":"assets/golden-fleece/2015/lessons/9-11/57.webp","alt":"Кирпичный фасад церкви","width":168,"height":126}},{"title":"Должность живописца","question":"Должность официального художника Венецианской республики называлась …","choices":["кондотьер","сенатор","сенсарий","дож"],"answer":2,"steps":["Сенсария была оплачиваемой должностью при венецианском торговом учреждении Фондако-деи-Тедески.","Её доход мог получать официальный живописец при выполнении работ для Республики."]},{"title":"Театр в Виченце","question":"Этот театр, один из старейших стационарных театров Европы, был спроектирован …","choices":["Д. Браманте","Микеланджело","Я. Сансовино","А. Палладио"],"answer":3,"steps":["Андреа Палладио разработал проект театра Олимпико по образцу античного театра.","После его смерти работу продолжил Винченцо Скамоцци, завершивший и уличные перспективы сцены."],"figure":{"src":"assets/golden-fleece/2015/lessons/9-11/59.webp","alt":"Театральная сцена с колоннами и видом улицы","width":169,"height":120}},{"title":"Сравнение Муратова","question":"Знаток итальянского искусства П.П. Муратов сравнивал творческие принципы А. Палладио и этого русского поэта.","choices":["А. Пушкин","М. Лермонтов","Н. Некрасов","А. Блок"],"answer":0,"steps":["Павел Муратов писал об архитектуре Палладио в «Образах Италии».","Он сближал классическую ясность его зданий и ясность пушкинской поэзии."]}]);
